#define PI 3.14159265359

const float fov = 60.*PI/180.;
const float D = .5/tan(fov/2.);

const float step = .5;
const float threshold = .01;
const float far2 = 1000.;
const float far = sqrt(far2);
const int max_steps = 10000;

const vec4 orange = vec4(1., .5, 0., 1.);
const vec4 white = vec4(1., 1., 1., 1.);

// orange, white, crease
const vec3 shininess = vec3(16., 32., 8.);
const vec3 roughness = vec3(.01, .2, .05);

const vec3 light_pos = vec3(50., 30., 50.);

const vec3 illumination = vec3(.3, .3, .2);
const vec3 ambient = vec3(.3, .4, .3);

const float occlusion_speed = .005;

vec4 sky(vec3 pos) {
    //return vec4(.8, .9, 1., 1.);
    return texture(iChannel0, normalize(pos));
}

vec3 rotate_point(vec3 point, vec3 rot) {
    float ca = cos(rot.x), sa = sin(rot.x);
    float cb = cos(rot.y), sb = sin(rot.y);
    float cc = cos(rot.z), sc = sin(rot.z);

    mat3 x_mat = mat3(1, 0, 0, 0, ca, -sa, 0, sa, ca);
    mat3 y_mat = mat3(cb, 0, sb, 0, 1, 0, -sb, 0, cb);
    mat3 z_mat = mat3(cc, -sc, 0, sc, cc, 0, 0, 0, 1);
    mat3 rot_mat = y_mat * z_mat * x_mat;

    return rot_mat * point;
}

vec3 cam_rot() {
    return vec3(0., iTime*.5, 0.);
}

vec3 cam_pos() {
    vec3 rot = cam_rot();
    return rotate_point(vec3(0., 0., 10.), rot);
}

bool is_orange(vec3 pos) {
    return pos.y < -2. || pos.y > 3. || mod(pos.y+.5, 2.5) < 1.25;
}

bool is_crease(vec3 pos) {
    float x = atan(pos.z, pos.x)*5.;
    float y = pos.y*4.;
    return mod(x+y, 1.) < .1 || mod(x-y, 1.) < .1;
}

float inner_sdf(vec3 pos, out vec3 normal) {
    //normal = normalize(pos);
    //return length(pos)-3.;

    const float angle = .28;
    const float top = 5.;
    const float base = -3.;

    const float round_height = 2.;

    const float base_size = 3.;
    const float base_thickness = .07;
    const float base_round_size = 2.5;

    vec3 abs_pos = vec3(abs(pos.x), abs(pos.y), abs(pos.z));

    // cone
    float lxz = length(pos.xz);
    float ca = cos(angle), sa = sin(angle);
    float _top = is_orange(pos) ? top : top + (is_crease(pos) ? -.05 : .05);
    float d0 = max(dot(vec2(ca, sin(angle)), vec2(lxz,pos.y-_top)),base-pos.y);

    if (pos.y < base) normal = vec3(0., -1., 0.);
    else normal = normalize(vec3(ca*pos.x/lxz, sa, ca*pos.z/lxz));
    float min_dist = d0;

    // cap
    vec3 moved = vec3(pos.x, pos.y-top+round_height, pos.z);
    float radius = sa*round_height;
    float d1 = length(moved) - radius;

    // use cap SDF when needed
    if (pos.y > top-round_height+radius*sa) {
        min_dist = d1;
        normal = normalize(moved);
    }

    // base
    float dy = abs(pos.y-base)-base_thickness;
    vec2 q = vec2(abs_pos.x, abs_pos.z) - base_round_size;
    float dxz = length(vec2(max(q.x, 0.), max(q.y, 0.))) + min(max(q.x, q.y), 0.) + base_round_size-base_size;
    float d2 = max(dy, dxz);
    float div = max(abs_pos.x, abs_pos.z);
    bool is_rounded_part = min(base_size*abs_pos.x/div, base_size*abs_pos.z/div) > base_round_size;
    //vec3 normal_around_base = is_rounded_part ? vec3(1., 0., 0.) : vec3(0., -1., 0.);
    vec3 normal_around_base;
    if (is_rounded_part) {
        vec3 closer = vec3(pos.x > 0. ? pos.x-base_round_size : pos.x+base_round_size, 0., pos.z > 0. ? pos.z-base_round_size : pos.z+base_round_size);
        normal_around_base = normalize(closer);
    }
    else {
        if (abs_pos.x > abs_pos.z) normal_around_base = vec3(pos.x > 0. ? 1. : -1., 0., 0.);
        else normal_around_base = vec3(0., 0., pos.z > 0. ? 1. : -1.);
    }
    vec3 normal2 = dy > dxz ? pos.y > base ? vec3(0., 1., 0.) : vec3(0., -1., 0.) : normal_around_base;

    if (d2 < min_dist) {
        min_dist = d2;
        normal = normal2;
    }

    return min_dist;
}

float sdf(vec3 pos, out vec3 normal, out bool has_escaped) {
    vec3 normal_object;
    float d1 = inner_sdf(pos, normal_object);

    vec3 normal_escape = -normalize(pos);
    float d2 = far - length(pos);

    if (d1 < d2) {
        normal = normal_object;
        has_escaped = false;
        return d1;
    }

    normal = normal_escape;
    has_escaped = d2 < threshold;
    return d2;
}

vec3 get_ray(vec2 uv) {
    vec3 pos = normalize(vec3((uv.x-.5)*iResolution.x/iResolution.y, uv.y-.5, -D));

    return rotate_point(pos, cam_rot());
}

bool raymarch(vec3 pos, vec3 ray, out vec3 final_pos, out vec3 normal, out float n_steps) {
    for(int steps = 0; steps < max_steps; steps++) {
        bool has_escaped;
        float d = sdf(pos, normal, has_escaped);

        n_steps = float(steps) + d/threshold; // smoothing
        final_pos = pos;

        if (has_escaped)
            return false;
        if (d < threshold)
            return true;

        pos += ray*d*step;
    }

    n_steps = float(max_steps);
    final_pos = pos;
    return false;
}

vec4 get_color(vec3 pos, vec3 ray) {
    for(int i=0;i<1;i++){ ///////// thanks, compiler optimizations

    // raymarching
    vec3 final_pos, normal;
    float n_steps; // floating point for smoothing
    bool hit = raymarch(pos, ray, final_pos, normal, n_steps);

    // coloring

    if (hit) {
        // hit an object

        bool o = is_orange(final_pos);
        bool c = is_crease(final_pos);
        float shine = o ? shininess.x : c ? shininess.z : shininess.y;
        vec4 albedo = o ? orange : white;
        float rough = o ? roughness.x : c ? roughness.z : roughness.y;

        vec3 reflected = normalize(ray + 2.*normal);
        vec3 abs_normal = vec3(abs(normal.x), abs(normal.y), abs(normal.z));
        float brightness = clamp(dot(normal, illumination), 0., 1.) + dot(abs_normal, ambient);

        float occlusion = 1. / exp(occlusion_speed * n_steps * step);

        vec3 light_dir = normalize(light_pos-final_pos);
        vec3 V = normalize(pos-final_pos);
        vec3 R = reflect(-light_dir, normal);
        float specular = pow(clamp(dot(R, V), 0., 1.), shine);

        // check if in shadow
        vec3 dummy1, dummy2;
        float dummy3;
        if (raymarch(final_pos+light_dir*threshold*2., light_dir, dummy1, dummy2, dummy3)) specular = 0.;

        float mult = brightness * occlusion;

        vec4 sky_color = sky(reflected);
        vec4 color1 = (albedo+specular) * mult;
        vec4 color2 = sky_color*albedo;
        return color1 + (color2-color1)*rough;
    }

    // hit the border, or timed out
    return sky(final_pos);

    } /////////
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    vec3 ray = get_ray(uv);

    fragColor = get_color(cam_pos(), ray);
}
